(() => {
  const layout=OfficeLayout,engine=new OfficeEngine(layout),T=layout.tile,W=layout.width*T,H=layout.height*T;
  state.officeTasks ||= [];state.officeChat ||= {};const taskKinds=['planning','research','analysis','coding','review'];
  const locations={planning:['manager','whiteboard','projectboard','meeting'],research:['research','bookshelf','booth-1'],analysis:['analysis','projectboard','discussion'],coding:['developer','pair','ai','booth-2','hotdesk'],review:['qa','meeting','discussion']};
  const labels={work:'Working',discuss:'Discussing',plan:'Planning',present:'Presenting',read:'Reading',research:'Researching',review:'Reviewing',analyse:'Analysing',print:'Printing',get_coffee:'Getting coffee',get_water:'Getting water',inspect:'Inspecting',organise:'Organising',sit:'Taking a break',take_break:'Taking a break',look_outside:'Looking outside',pet_cat:'Petting the cat',water_plant:'Tending a plant'};
  let chosen=0,hovered=null,canvas,ctx,background,raf=0,last=performance.now(),lastPanel=0,panelHTML='',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,roam=true,zoom=0,message='Select a teammate, then click a location or open floor.',saveTimer;
  const actors=state.agents.map((_,i)=>{const saved=state.officePositionsV4?.[i],fallback=layout.spawns[i%layout.spawns.length],p=saved&&engine.walkable(saved.x,saved.y)?saved:fallback;return {x:(p.x+.5)*T,y:(p.y+.75)*T,slot:null,path:[],direction:'down',clock:0,location:'Office floor',objectId:null,mode:'Idle',taskId:null,reason:null,holdUntil:0,nextAmbient:performance.now()+3500+i*1700}});
  function tile(a){return {x:Math.floor(a.x/T),y:Math.floor(a.y/T)}}
  function savePositions(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{state.officePositionsV4=actors.map(tile);persist()},400)}
  function say(text){message=text;const el=$('#office-message');if(el)el.textContent=text}
  function taskFor(i){const p=state.projects.find(p=>p.status==='Running'&&p.tasks[p.step]?.agent===i);if(p)return {id:p.id+':'+p.step,title:p.tasks[p.step].title,kind:taskKinds[i%5],project:p};const direct=state.officeTasks.find(t=>t.agent===i&&['Queued','Running'].includes(t.status));return direct?{...direct,direct}:null}
  function clearInteraction(i){engine.release(i);const a=actors[i];a.objectId=null;a.slot=null;a.reason=null;a.holdUntil=0}
  function goLocation(i,ids,reason='manual',now=performance.now()){
    const a=actors[i];if(reason!=='task'&&taskFor(i)){say(`${state.agents[i].name} has an assigned task. Task activity takes priority.`);return false}
    const found=engine.choose(i,ids,tile(a));if(!found){if(reason==='task'){a.mode='Waiting for a free station';a.path=[]}else say('Those locations are occupied or unreachable. Try another location.');return false}
    a.path=found.route;a.objectId=found.object.id;a.slot=found.slot;a.reason=reason;a.mode=a.path.length?'Walking':labels[found.object.actions?.[0]]||'Using location';a.location=a.path.length?'On the way to '+found.object.name:found.object.name;a.holdUntil=now+9000+Math.random()*4000;
    if(!a.path.length)arrive(i,now);if(reason==='manual')say(`${state.agents[i].name} → ${found.object.name}${found.object.id!==ids[0]?' (alternative free location)':''}.`);updatePanel();return true;
  }
  function move(i,p){if(taskFor(i)){say('An assigned task takes priority. Choose an idle teammate to move manually.');return}const a=actors[i],route=engine.route(tile(a),p);if(route===null){say('Choose an open floor tile. Furniture and walls block walking.');return}clearInteraction(i);a.path=route;a.mode=route.length?'Walking':'Idle';a.location='Office floor';a.nextAmbient=performance.now()+14000;say(`${state.agents[i].name} is ${route.length?'walking there':'already there'}.`)}
  function arrive(i,now){const a=actors[i];if(a.slot?.face)a.direction=a.slot.face;if(a.objectId){const o=engine.objects.get(a.objectId);a.location=o.name;a.mode=labels[o.actions?.[0]]||'Using location';a.holdUntil=now+8000;if(a.reason==='task')a.mode='Working';}else a.mode='Idle';a.nextAmbient=now+6000+Math.random()*7000;savePositions();if(i===chosen)say(`${state.agents[i].name} arrived at ${a.location.toLowerCase()}.`)}
  function update(dt,now){actors.forEach((a,i)=>{
    const task=taskFor(i);
    if((task?.id||null)!==a.taskId){if(a.taskId&&!task)a.doneUntil=now+3000;clearInteraction(i);a.taskId=task?.id||null;a.path=[];a.mode='Idle';if(task){goLocation(i,locations[task.kind]||locations[taskKinds[i%5]],'task',now);if(task.direct){task.direct.status='Running';persist()}}else a.nextAmbient=now+4000}
    if(task&&!a.objectId&&now>a.nextAmbient){goLocation(i,locations[task.kind]||locations.planning,'task',now);a.nextAmbient=now+1500}
    if(!paused){a.clock+=dt;if(a.path.length){const p=a.path[0],x=(p.x+.5)*T,y=(p.y+.75)*T,dx=x-a.x,dy=y-a.y,d=Math.hypot(dx,dy),step=dt*.055*T/16;a.direction=Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up';if(d<=step){a.x=x;a.y=y;a.path.shift();if(!a.path.length)arrive(i,now)}else{a.x+=dx/d*step;a.y+=dy/d*step}}
      else if(!task&&a.objectId&&now>a.holdUntil){clearInteraction(i);a.mode='Idle';a.nextAmbient=now+2500}
      else if(!task&&roam&&!a.path.length&&!a.objectId&&now>a.nextAmbient){const candidates=engine.interactions.filter(o=>['break','fun','research'].includes(o.kind)).map(o=>o.id);const start=Math.floor(Math.random()*candidates.length);goLocation(i,[...candidates.slice(start),...candidates.slice(0,start)],'ambient',now);a.nextAmbient=now+9000}
    }
    if(task?.direct&&!a.path.length&&a.objectId){task.direct.remainingMs=Math.max(0,task.direct.remainingMs-dt);if(task.direct.remainingMs===0){task.direct.status='Completed';task.direct.output='Simulated task completed. No AI provider or tool was called.';log(`${state.agents[i].name} completed demo task “${task.title}”.`);persist();a.taskId=null;a.doneUntil=now+3000;clearInteraction(i);a.mode='Idle';a.nextAmbient=now+6000;say(`${state.agents[i].name} completed the demo task.`)}}
  })}
  // The office is the V2 backdrop image; furniture is painted into it, so only people and status are drawn live.
  function makeBackground(){const img=new Image();img.src=layout.background;background=img}
  const CH=58,iconSize=20;// on-screen employee height and status glyph size, in backdrop pixels
  function seatOffset(a){return !a.path.length&&a.slot?{x:(a.slot.dx||0)*T,y:(a.slot.dy||0)*T}:{x:0,y:0}}
  function drawHover(){const o=hovered?.object&&engine.objects.get(hovered.object);if(!o)return;ctx.strokeStyle='rgba(229,199,123,.9)';ctx.lineWidth=2;ctx.setLineDash([6,4]);ctx.strokeRect(o.x*T+1,o.y*T+1,o.width*T-2,o.height*T-2);ctx.setLineDash([])}
  function actionFor(a){return a.path.length&&!paused?'walk':'idle'}
  function drawAgent(a,i){const off=seatOffset(a),cx=Math.round(a.x+off.x),y=Math.round(a.y+off.y);if(i===chosen){ctx.fillStyle='rgba(229,199,123,.55)';ctx.beginPath();ctx.ellipse(cx,y-2,15,5,0,0,Math.PI*2);ctx.fill()}AgentSkins.draw(ctx,i,actionFor(a),a.direction,Math.floor(a.clock/150)%4,cx-8*CH/24,y,CH/24)}
  // Status icons are secondary: only meaningful states get one, at most MAX_ICONS on screen, highest priority first.
  // Walking, idle and ambient breaks (coffee, sofa, window) never show an icon.
  const MAX_ICONS=5,iconPriority={approval:0,thinking:1,waiting:1,done:2,team:3,research:3,working:4};
  function iconFor(a,i,now){if(i===0&&state.projects.some(p=>p.status==='Waiting approval'))return 'approval';if(wins.get(i)?.typing)return 'thinking';if(a.mode==='Waiting for a free station')return 'waiting';if(a.doneUntil>now)return 'done';const task=taskFor(i);if(!task||a.path.length||!a.objectId)return null;const kind=engine.objects.get(a.objectId)?.kind;return kind==='research'||task.kind==='research'?'research':kind==='collaboration'?'team':'working'}
  function drawIcons(now){actors.map((a,i)=>({a,icon:iconFor(a,i,now)})).filter(s=>s.icon).sort((s,t)=>iconPriority[s.icon]-iconPriority[t.icon]).slice(0,MAX_ICONS).forEach(({a,icon})=>{const off=seatOffset(a),bob=icon==='approval'&&!paused&&Math.floor(now/400)%2?2:0;V2Sprites.icon(ctx,icon,a.x+off.x,a.y+off.y-CH-16-bob,iconSize)})}
  function draw(now){if(!canvas?.isConnected){raf=0;return}const dt=Math.min(now-last,50);last=now;update(dt,now);ctx.clearRect(0,0,W,H);if(background?.complete)ctx.drawImage(background,0,0,W,H);else{ctx.fillStyle='#101a24';ctx.fillRect(0,0,W,H)}drawHover();actors.map((a,i)=>({a,i})).sort((p,q)=>p.a.y-q.a.y).forEach(({a,i})=>drawAgent(a,i));drawIcons(now);drawLinks();positionWins();const dest=actors[chosen].path.at(-1);if(dest){ctx.strokeStyle='#e5c77b';ctx.lineWidth=2;const x=(dest.x+.5)*T,y=(dest.y+.75)*T;ctx.beginPath();ctx.ellipse(x,y-2,10,4,0,0,Math.PI*2);ctx.stroke()}if(now-lastPanel>500){updatePanel();lastPanel=now}raf=requestAnimationFrame(draw)}
  function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
  function pick(p){const agent=actors.map((a,i)=>({a,i})).reverse().find(({a})=>{const off=seatOffset(a);return Math.abs(a.x+off.x-p.x)<16&&p.y>=a.y+off.y-CH-30&&p.y<=a.y+off.y+4});/* hit area includes the status icon, so clicking an approval icon opens that teammate */if(agent)return {agent:agent.i};const object=[...engine.interactions].reverse().find(o=>p.x>=o.x*T&&p.x<(o.x+o.width)*T&&p.y>=o.y*T&&p.y<(o.y+o.height)*T);return object?{object:object.id}:null}
  // ---- Floating employee windows -------------------------------------------------------------
  // Clicking a teammate opens a card anchored above them that follows them as they walk. Dragging the
  // header detaches it (a dashed line still links it to the teammate). Minimised windows live in the dock.
  const wins=new Map();let zTop=10,moveArmed=null;const narrow=matchMedia('(max-width:700px)');
  const agentKey=i=>state.agents[i].id||`employee-${i}`;
  const approvalFor=i=>i===0?state.projects.find(p=>p.status==='Waiting approval'):null;
  function saveWins(){state.officeWindows=[...wins].map(([agent,w])=>({agent,mode:w.mode,detached:w.detached,x:w.x,y:w.y,min:w.min}));persist()}
  function stageScale(){return canvas?canvas.clientWidth/W:1}
  function portrait(c,i,h){const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);AgentSkins.draw(g,i,'idle','down',0,c.width/2-8*h/24,h,h/24)}
  function selected(i){chosen=i;hovered=null;openWin(i)}
  function openWin(i,mode){let w=wins.get(i);if(!w){w={mode:mode||'card',detached:false,x:0,y:0,min:false};wins.set(i,w)}if(mode)w.mode=mode;w.min=false;w.unread=false;chosen=i;buildWin(i);focusWin(i);refreshDock();saveWins()}
  function closeWin(i){wins.get(i)?.el?.remove();wins.delete(i);if(moveArmed===i)moveArmed=null;refreshDock();saveWins()}
  function minimiseWin(i){const w=wins.get(i);if(!w)return;w.min=true;w.el?.remove();w.el=null;refreshDock();saveWins()}
  function focusWin(i){const w=wins.get(i);if(!w?.el)return;w.z=++zTop;w.el.style.zIndex=w.z;document.querySelectorAll('.ow.top').forEach(e=>e.classList.remove('top'));w.el.classList.add('top')}
  function topWin(){return [...wins].filter(([,w])=>w.el).sort((a,b)=>(b[1].z||0)-(a[1].z||0))[0]?.[0]}
  function infoHTML(i){const a=actors[i],task=taskFor(i),p=approvalFor(i);return `${p?`<div class="ow-approval"><b>Approval needed</b><span>${esc(p.name)}</span><button class="primary" data-approve="${p.id}">Review approval</button></div>`:''}<dl><dt>Task</dt><dd>${task?esc(task.title):'No assigned task'}</dd><dt>Where</dt><dd>${esc(a.location)}</dd></dl>`}
  function chatHTML(i){const log=state.officeChat[agentKey(i)]||[],w=wins.get(i);return (log.slice(-30).map(m=>`<p class="${m.who==='You'?'me':'them'}">${esc(m.text)}</p>`).join('')||`<p class="ow-empty">Say hello to ${esc(state.agents[i].name)}.</p>`)+(w?.typing?'<p class="them typing" aria-label="Typing"><span></span><span></span><span></span></p>':'')}
  function buildWin(i){const w=wins.get(i),agent=state.agents[i],layer=$('#office-windows');if(!layer)return;w.el?.remove();
    const el=document.createElement('section');el.className='ow';el.dataset.win=i;el.setAttribute('role','dialog');el.setAttribute('aria-label',`${agent.name} window`);
    el.innerHTML=`<span class="ow-tail" aria-hidden="true"></span><header class="ow-head" title="Drag to move"><canvas width="32" height="48" aria-hidden="true"></canvas><div class="ow-title"><b>${esc(agent.name)}</b><small>${esc(agent.role)}</small><span class="ow-status"></span></div><button class="ow-icon" data-win-action="min" aria-label="Minimise">–</button><button class="ow-icon" data-win-action="close" aria-label="Close">✕</button></header>
      <nav class="ow-tabs"><button data-win-action="card" aria-pressed="${w.mode==='card'}">Info</button><button data-win-action="chat" aria-pressed="${w.mode==='chat'}">Chat</button></nav>
      ${w.mode==='card'?`<div class="ow-info"></div><div class="ow-actions"><button class="primary" data-win-action="assign">Assign task</button><button data-win-action="desk">Go to desk</button><button data-win-action="move">Move</button><details class="ow-more"><summary aria-label="More actions">⋯</summary><div><button data-win-action="details">Employee details</button><button data-win-action="appearance">Appearance</button></div></details></div>`
      :`<div class="ow-msgs" aria-live="polite"></div><form class="ow-form"><input maxlength="500" placeholder="Message ${esc(agent.name)}…" aria-label="Message ${esc(agent.name)}" required><button class="primary">Send</button></form><p class="ow-note">Demo chat · replies are scripted until an AI connection is wired in.</p>`}`;
    layer.append(el);w.el=el;w.info='';portrait(el.querySelector('canvas'),i,48);refreshWin(i,true);
    const msgs=el.querySelector('.ow-msgs');if(msgs){msgs.innerHTML=chatHTML(i);msgs.scrollTop=msgs.scrollHeight;el.querySelector('input').focus()}
    el.addEventListener('pointerdown',()=>{focusWin(i);chosen=i});
    el.querySelector('.ow-form')?.addEventListener('submit',e=>{e.preventDefault();const input=e.target.querySelector('input'),text=input.value.trim();if(text){input.value='';sendChat(i,text)}});
    dragHandle(el.querySelector('.ow-head'),i);positionWins()}
  function refreshWin(i,force){const w=wins.get(i);if(!w?.el)return;const status=badge(actors[i].mode,taskFor(i)?'demo':'');if(force||w.status!==status){w.status=status;w.el.querySelector('.ow-status').innerHTML=status}const info=w.el.querySelector('.ow-info');if(info){const html=infoHTML(i);if(force||html!==w.info){w.info=html;info.innerHTML=html}}}
  function refreshChat(i){const msgs=wins.get(i)?.el?.querySelector('.ow-msgs');if(msgs){msgs.innerHTML=chatHTML(i);msgs.scrollTop=msgs.scrollHeight}}
  function sendChat(i,text){const k=agentKey(i),log=state.officeChat[k] ||= [];log.push({who:'You',text});const w=wins.get(i);w.typing=true;refreshChat(i);persist();
    setTimeout(()=>{log.push({who:state.agents[i].name,text:`(Demo reply) Noted — I'm ${state.agents[i].role.toLowerCase()} here. Use Assign task to see me work; real replies need an AI connection in Settings.`});state.officeChat[k]=log.slice(-40);persist();const cur=wins.get(i);if(cur){cur.typing=false;if(!cur.el)cur.unread=true}refreshChat(i);refreshDock()},1400)}
  function dragHandle(head,i){let start=null;head.addEventListener('pointerdown',e=>{if(e.target.closest('button')||narrow.matches)return;const w=wins.get(i),r=w.el.getBoundingClientRect(),stage=$('.office-pixel-stage').getBoundingClientRect();start={px:e.clientX,py:e.clientY,x:r.left-stage.left,y:r.top-stage.top,moved:false};head.setPointerCapture(e.pointerId)});
    head.addEventListener('pointermove',e=>{if(!start)return;const w=wins.get(i),dx=e.clientX-start.px,dy=e.clientY-start.py;if(!start.moved&&Math.hypot(dx,dy)<4)return;start.moved=true;w.detached=true;w.x=start.x+dx;w.y=start.y+dy;positionWins()});
    head.addEventListener('pointerup',()=>{if(start?.moved)saveWins();start=null})}
  function positionWins(){const stage=$('.office-pixel-stage');if(!stage||!canvas)return;const s=stageScale(),sw=stage.clientWidth,sh=stage.clientHeight;
    for(const [i,w] of wins){const el=w.el;if(!el)continue;el.classList.toggle('sheet',narrow.matches);if(narrow.matches)continue;const ww=el.offsetWidth,wh=el.offsetHeight;let left,top,below=false;
      if(w.detached){left=w.x;top=w.y}else{const a=actors[i],off=seatOffset(a),sx=(a.x+off.x)*s;left=sx-ww/2;top=(a.y+off.y-CH-10)*s-wh-12;if(top<4){top=(a.y+off.y)*s+14;below=true}el.style.setProperty('--tail',Math.round(Math.min(Math.max(sx-Math.max(4,Math.min(left,sw-ww-4)),14),ww-14))+'px')}
      left=Math.max(4,Math.min(left,sw-ww-4));top=Math.max(4,Math.min(top,sh-wh-4));if(w.detached){w.x=left;w.y=top}
      el.style.transform=`translate(${Math.round(left)}px,${Math.round(top)}px)`;el.classList.toggle('detached',w.detached);el.classList.toggle('below',below)}}
  function drawLinks(){const s=stageScale();ctx.save();ctx.strokeStyle='rgba(229,199,123,.7)';ctx.lineWidth=2/s;ctx.setLineDash([6/s,5/s]);for(const [i,w] of wins){if(!w.el||!w.detached||narrow.matches)continue;const a=actors[i],off=seatOffset(a),wx=(w.x+w.el.offsetWidth/2)/s,wy=(w.y+w.el.offsetHeight/2)/s;ctx.beginPath();ctx.moveTo(a.x+off.x,a.y+off.y-CH);ctx.lineTo(wx,wy);ctx.stroke()}ctx.restore()}
  function refreshDock(){document.querySelectorAll('.dock-item').forEach(b=>{const i=Number(b.dataset.officeAgent),w=wins.get(i);b.classList.toggle('open',!!w&&!w.min);b.classList.toggle('minimised',!!w?.min);const alert=!!approvalFor(i)||!!w?.unread;b.classList.toggle('alert',alert);b.setAttribute('aria-label',`${state.agents[i].name}${w?.min?' (minimised)':''}${alert?' — needs attention':''}`)})}
  function updatePanel(force=false){for(const i of wins.keys())refreshWin(i,force);refreshDock()}
  function winAction(i,action){chosen=i;const w=wins.get(i);
    if(action==='close')closeWin(i);else if(action==='min')minimiseWin(i);else if(action==='card'||action==='chat'){w.mode=action;buildWin(i);focusWin(i);saveWins()}
    else if(action==='assign')assign(i);else if(action==='desk')goLocation(i,[layout.homeByAgent[i%5]]);else if(action==='details')employee(i);else if(action==='appearance')AgentSkins.appearance(i);
    else if(action==='move'){if(taskFor(i)){say('An assigned task takes priority over manual movement.');return}moveArmed=i;canvas.classList.add('armed');say(`Click a spot or a place in the office to send ${state.agents[i].name} there. Esc cancels.`)}}
  function disarm(){moveArmed=null;canvas?.classList.remove('armed')}
  function mount(){canvas=$('#office-canvas');ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;canvas.style.width=zoom?W+'px':'100%';canvas.style.height='auto';
    canvas.addEventListener('pointerdown',e=>{canvas.focus();const p=point(e),hit=pick(p);
      if(hit?.agent!==undefined){disarm();selected(hit.agent);return}
      if(moveArmed!==null){const i=moveArmed;disarm();if(paused){say('Resume motion to send a teammate somewhere.');return}if(hit?.object){const o=engine.objects.get(hit.object);goLocation(i,[o.id,...engine.interactions.filter(x=>x.kind===o.kind&&x.id!==o.id).map(x=>x.id)])}else{chosen=i;move(i,{x:Math.floor(p.x/T),y:Math.floor(p.y/T)})}return}
      if(!hit)for(const [i,w] of [...wins])if(!w.detached&&w.mode==='card'&&w.el)closeWin(i)});
    canvas.addEventListener('pointermove',e=>{const p=point(e);hovered=pick(p);const tip=$('#office-tooltip');if(!hovered){tip.hidden=true;return}tip.textContent=hovered.agent!==undefined?state.agents[hovered.agent].name:(()=>{const o=engine.objects.get(hovered.object);return `${o.name} · ${engine.occupancy(o.id)}/${o.capacity} in use`})();tip.hidden=false;tip.style.left=Math.min(e.offsetX+12,canvas.clientWidth-170)+'px';tip.style.top=Math.max(0,e.offsetY-32)+'px'});canvas.addEventListener('pointerleave',()=>{hovered=null;$('#office-tooltip').hidden=true});
    canvas.addEventListener('keydown',e=>{const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]){e.preventDefault();if(paused)return;const a=actors[chosen],p=a.path.at(-1)||tile(a),[dx,dy]=dirs[e.key];move(chosen,{x:p.x+dx,y:p.y+dy})}if(e.key==='Enter')openWin(chosen)});
    document.querySelectorAll('.dock-item canvas').forEach(c=>portrait(c,Number(c.closest('.dock-item').dataset.officeAgent),36));
    for(const [i,w] of wins){w.el=null;if(!w.min)buildWin(i)}refreshDock();if(!raf){last=performance.now();raf=requestAnimationFrame(draw)}}
  function assign(i=chosen){show(`<h2>Assign a task to ${esc(state.agents[i].name)}</h2><p class="notice">This is a local simulation. No AI provider or execution tool is connected.</p><form id="office-task-form"><label for="office-task-title">Task</label><input id="office-task-title" name="title" required maxlength="120" placeholder="e.g. Review the prototype"><label for="office-task-kind">Activity</label><select name="kind" id="office-task-kind">${taskKinds.map(k=>`<option value="${k}" ${taskKinds[i%5]===k?'selected':''}>${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Assign demo task</button></div></form>`);$('#office-task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title)return;state.officeTasks.push({id:crypto.randomUUID(),agent:i,title,kind:f.get('kind'),status:'Queued',remainingMs:14000});log(`Assigned demo task “${title}” to ${state.agents[i].name}.`);persist();$('#dialog').close();updatePanel(true)}}
  const baseBody=bodyView;bodyView=function(p){let html=baseBody(p);if(view==='Tasks'&&state.officeTasks.length)html=`<section class="panel office-task-list"><div class="panel-head"><h2>Direct employee tasks · demo</h2></div>${state.officeTasks.slice().reverse().map(t=>`<div class="task"><div class="task-main"><h3>${esc(t.title)}</h3><p class="muted">${esc(state.agents[t.agent]?.name)} · ${esc(t.kind)}</p></div>${badge(t.status)}${t.status==='Completed'?'<span class="small muted">Simulated result</span>':''}</div>`).join('')}</section>`+html;return html};
  const baseRender=render;render=function(){baseRender();document.title='Ruang — Pixel Office';const brand=$('.brand');if(brand)brand.innerHTML='<span class="ruang-mark">R</span> RUANG';if($('.tagline'))$('.tagline').textContent='Idea besar. Ruang sendiri.';if(view!=='Office')return;
    const p=project();$('.main').innerHTML=`<header class="topbar"><div><div class="eyebrow">RUANG / YOUR LOCAL AI WORKSPACE</div><h1>Your office, in motion.</h1><p class="welcome-sub">Small team. Shared space. Big ideas.</p></div><div class="top-actions">${badge(window.desktop?'Desktop · AI demo':'AI demo','demo')}<button class="primary" data-action="new-project">＋ New project</button></div></header>
      <section class="panel office-simulation"><div class="room-toolbar"><div><strong>Our office</strong><span class="small muted">${state.agents.length} teammates</span></div><div><button data-office="pause">${paused?'▶ Resume':'Ⅱ Pause'}</button><button data-office="roam" aria-pressed="${roam}">Wander ${roam?'on':'off'}</button><button data-office="zoom" aria-label="Change office zoom">${zoom?'100%':'Fit'}</button></div></div>
      <div class="office-viewport"><div class="office-pixel-stage" style="width:${zoom?W+'px':'100%'}"><canvas id="office-canvas" width="${W}" height="${H}" tabindex="0" role="application" aria-label="Pixel office. Click a teammate to open their window. Arrow keys walk the selected teammate; Enter opens their window."></canvas><div id="office-tooltip" hidden></div><div id="office-windows"></div></div></div>
      <div class="room-hint"><span id="office-message" role="status">${esc(message)}</span><span class="keyboard-hint">Click a teammate to talk · Esc closes</span></div>
      <div class="office-dock" role="toolbar" aria-label="Teammates">${state.agents.map((a,i)=>`<button class="dock-item" data-office-agent="${i}"><canvas width="24" height="36" aria-hidden="true"></canvas><span><b>${esc(a.name)}</b><small>${esc(a.role)}</small></span><i class="dock-dot" aria-hidden="true"></i></button>`).join('')}</div></section>
      <div class="office-lower"><section class="panel pad"><div class="row"><h2>Project board</h2>${p?badge(p.status):''}</div>${p?projectSummary(p):'<p class="muted small">Try a project to watch the team at work.</p><button class="primary" data-action="demo">Try a demo project</button>'}</section><section class="panel activity"><div class="panel-head"><h2>Recent activity</h2><button class="quiet small" data-view="Activity">View all</button></div>${eventsHTML(3)}</section></div>
      <p class="small muted room-note">Office actions and AI chat are simulated. Local file editing under Files is real.</p>`;mount()};
  document.addEventListener('click',e=>{const wa=e.target.closest('[data-win-action]');if(wa){winAction(Number(wa.closest('.ow').dataset.win),wa.dataset.winAction);return}
    const b=e.target.closest('[data-office],[data-office-agent]');if(!b)return;if(b.dataset.officeAgent!==undefined){const i=Number(b.dataset.officeAgent);wins.get(i)&&!wins.get(i).min&&wins.get(i).el?closeWin(i):selected(i);return}const action=b.dataset.office;
    if(action==='pause'){paused=!paused;render()}if(action==='roam'){roam=!roam;if(!roam)actors.forEach((a,i)=>{if(a.reason==='ambient'){clearInteraction(i);a.path=[];a.mode='Idle'}});render()}if(action==='zoom'){zoom=zoom?0:1;render()}});
  document.addEventListener('keydown',e=>{if(e.key!=='Escape'||view!=='Office'||$('#dialog')?.open)return;if(moveArmed!==null){disarm();say('Move cancelled.');return}const i=topWin();if(i!==undefined){e.preventDefault();closeWin(i)}});
  addEventListener('resize',positionWins);narrow.addEventListener?.('change',positionWins);
  for(const s of state.officeWindows||[])if(state.agents[s.agent])wins.set(s.agent,{mode:s.mode==='chat'?'chat':'card',detached:!!s.detached,x:s.x||0,y:s.y||0,min:!!s.min});
  makeBackground();render();
})();
